import { useSelector } from 'react-redux';
import { selectActiveChat } from '../../store/slices/chatSlice';
import { selectSidebarOpen } from '../../store/slices/uiSlice';
import Sidebar    from '../layout/Sidebar';
import Header     from '../layout/Header';
import MessageList from '../chat/MessageList';
import ChatInput   from '../chat/ChatInput';
import { useTheme } from '../../hooks/useTheme';

export default function ChatPage() {
  const { bgHex, sidebarHex, borderHex, textHex, mutedHex } = useTheme();
  const sidebarOpen = useSelector(selectSidebarOpen);
  const activeChat = useSelector(selectActiveChat);
  const hasUserMessages = activeChat?.messages?.some((message) => message.role === 'user');

  return (
    <div style={{ display: 'flex', height: '100vh', background: bgHex, fontFamily: "'DM Sans', sans-serif", overflow: 'hidden' }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        @keyframes bounce3  { 0%,80%,100%{transform:translateY(0)} 40%{transform:translateY(-6px)} }
        @keyframes fadeUp   { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:translateY(0)} }
        @keyframes pulse2   { 0%,100%{opacity:1} 50%{opacity:0.5} }
        @keyframes spin     { to{transform:rotate(360deg)} }
        ::-webkit-scrollbar       { width:4px }
        ::-webkit-scrollbar-track { background:transparent }
        ::-webkit-scrollbar-thumb { background:#2e2e42; border-radius:99px }
      `}</style>

      {/* Sidebar */}
      <div style={{
        width: sidebarOpen ? 260 : 52, minWidth: sidebarOpen ? 260 : 52,
        background: sidebarHex,
        borderRight: `1px solid ${borderHex}`, overflow: 'hidden',
        transition: 'width 0.25s ease, min-width 0.25s ease', flexShrink: 0,
      }}>
        <Sidebar collapsed={!sidebarOpen}/>
      </div>

      {/* Main */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden', position: 'relative' }}>
        <Header/>
        {hasUserMessages ? (
          <>
            <MessageList/>
            <ChatInput/>
          </>
        ) : (
          <div style={{ flex: 1, overflowY: 'auto', padding: '40px 20px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ width: 'min(820px, 100%)', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 22, transform: 'translateY(-28px)' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12, opacity: 0.8 }}>
                <div style={{ width: 64, height: 64, borderRadius: 20, background: 'linear-gradient(135deg,#6366f1,#8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <svg width="32" height="32" viewBox="0 0 28 28" fill="none"><circle cx="14" cy="14" r="12" stroke="white" strokeWidth="2"/><circle cx="10" cy="12.5" r="2" fill="white"/><circle cx="18" cy="12.5" r="2" fill="white"/><path d="M10 18c1.2 1.5 6.8 1.5 8 0" stroke="white" strokeWidth="1.5" strokeLinecap="round"/></svg>
                </div>
                <p style={{ fontSize: 28, fontWeight: 700, color: textHex, fontFamily: "'Space Grotesk'", lineHeight: 1.15 }}>How can I help you?</p>
                <p style={{ fontSize: 14, color: mutedHex }}>Start a conversation below</p>
              </div>
              <ChatInput centered/>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
